const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // The question asks about Tshopo province in the DRC.
  // We use the FAO GAUL level 1 administrative dataset to get the province geometry.
  const adminBoundaries = ee.FeatureCollection('FAO/GAUL/2015/level1');
  const tshopoProvince = adminBoundaries.filter(ee.Filter.eq('ADM1_NAME', 'Tshopo'));

  if (tshopoProvince.size().getInfo() === 0) {
      console.log("Could not find Tshopo province geometry.");
      console.log("C1"); // Technically a geometry failure, but C1 is closest.
      return;
  }
  const geometry = tshopoProvince.geometry();

  // 2. Data Acquisition
  // Hansen Global Forest Change dataset is ideal for this analysis.
  // It provides data on tree cover, loss, and gain.
  const hansenImage = ee.Image('UMD/hansen/global_forest_change_2022_v1_10');

  // 3. Processing
  // We define a forest as an area with >30% tree cover in 2000.
  const treeCover2000 = hansenImage.select('treecover2000');
  const forestMask = treeCover2000.gt(30);

  // The 'loss' band is a binary image where 1 represents loss between 2000 and 2022.
  const lossImage = hansenImage.select('loss');
  const forestLoss = lossImage.updateMask(forestMask); // Apply the forest definition mask

  // Create an image where each pixel value is its area in square kilometers.
  const pixelArea = ee.Image.pixelArea().divide(1000 * 1000); // Convert from sq meters to sq km
  const lossAreaImage = forestLoss.multiply(pixelArea);

  // 4. Calculation
  // Sum the area of all loss pixels within the province geometry.
  // A high scale (3000m) is used to prevent timeout on such a large area.
  const stats = lossAreaImage.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: geometry,
      scale: 3000,
      maxPixels: 1e10
  });

  const totalLossSqKm = stats.get('loss').getInfo();

  // 5. Validation & Final Answer
  if (totalLossSqKm === null || totalLossSqKm === undefined) {
      console.log("Calculation failed: The result was null or undefined.");
      console.log("C3");
      return;
  }

  // Check the number of pixels to ensure the area wasn't empty
  const pixelCount = lossImage.updateMask(forestMask).reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: geometry,
      scale: 3000,
      maxPixels: 1e10
  }).get('loss').getInfo();

  if (pixelCount === 0) {
      console.log("No valid pixels with forest loss found in the region.");
      console.log("C2");
      return;
  }

  const thresholdSqKm = 15000;
  const isLossLess = totalLossSqKm < thresholdSqKm;

  console.log(`Region: Tshopo Province, DRC`);
  console.log(`Analysis Period: 2001-2022`);
  console.log(`Forest Definition: >30% tree cover in 2000`);
  console.log(`Total Forest Loss (sq km): ${totalLossSqKm.toFixed(2)}`);
  console.log(`Threshold (sq km): ${thresholdSqKm}`);
  console.log(`Was the loss less than ${thresholdSqKm} sq km? ${isLossLess}`);
  console.log(`Loss Pixels Counted: ${pixelCount}`);

  if (isLossLess) {
      console.log("A");
  } else {
      console.log("B");
  }
}

async function initEE() {
  try {
    await new Promise((resolve, reject) => {
      ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
      ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
  } catch (e) {
    console.error(`Initialization or analysis failed: ${e}`);
    console.log("D");
  }
}

initEE();
